#!/usr/bin/env python3
#
# Verilator + cocotb + LitePCIe minimal demo
# Step 1/4: turn LitePCIe's own Python/migen sources into simulatable Verilog.
#
# Almost none of LitePCIe's RTL exists as hand-written .v files -- it is
# generated by migen from Python descriptions. So the first step of "run LitePCIe
# under Verilator" is necessarily to export the module of interest as a
# standalone Verilog toplevel.
#
# The DUT chosen here is LitePCIeTLPPacketizer: it packs LitePCIe's internal
# request stream (a stream.Endpoint) into real PCIe TLP packets (including the
# TLP header). It is the most central piece of pure RTL in LitePCIe and by far
# the easiest to verify in isolation.
#
import argparse
import json
import os
import re
import sys

DEMO_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
VENDOR    = os.path.join(DEMO_ROOT, "vendor", "litepcie-master")
if VENDOR not in sys.path:
    sys.path.insert(0, VENDOR)

from migen import *
from migen.fhdl import verilog as migen_verilog

from litex.gen import *

from litepcie.tlp.packetizer import LitePCIeTLPPacketizer

# LiteX ships a `convert` wrapper around migen's that also applies LiteXContext
# special overrides; fall back to migen's own implementation if unavailable.
try:
    from litex.gen.fhdl.verilog import convert as hdl_convert
except Exception:                                    # pragma: no cover
    hdl_convert = migen_verilog.convert

from migen.fhdl.tools import list_clock_domains

TOP = "litepcie_tlp_packetizer"

# The stream.Endpoints on the DUT that should become toplevel ports.
ENDPOINTS = ("req_sink", "cmp_sink", "ptm_sink", "source")

# An Endpoint is internally a Record{valid, ready, first, last, payload, param}.
# `payload` / `param` are implementation details from the user's point of view
# (Endpoint.__getattr__ forwards attribute access to payload), so they are
# flattened away and the resulting port names read as req_sink_we / source_dat.
_FLATTEN = ("payload", "param")


def flat_fields(record, prefix):
    """Recursively flatten one Record into (flat_port_name, leaf_signal) pairs.

    This walks the layout by hand instead of calling `Record.flatten()` because
    flatten() returns only the signals and throws the names away -- and the names
    are exactly what needs fixing here (see `collect_ports` below).
    """
    for field in record.layout:
        name, spec = field[0], field[1]
        value      = getattr(record, name)
        if isinstance(spec, list):                       # nested sub-Record
            sub_prefix = prefix if name in _FLATTEN else "%s_%s" % (prefix, name)
            yield from flat_fields(value, sub_prefix)
        else:                                            # leaf Signal
            yield "%s_%s" % (prefix, name), value


def collect_ports(dut):
    """Collect the leaf signals of each Endpoint into prefixed toplevel ports.

    Why the explicit renaming is necessary: when emitting Verilog, the port name
    comes from `Signal.name_override` (LiteX's verilog.py fills in a name derived
    from the backtrace for any signal in `ios` whose `name_override` is still
    None -- which yields the bare field names `we` / `adr` / `first` / ...).
    Many of LitePCIe's Endpoints are never named (e.g.
    `self.req_sink = req_sink = stream.Endpoint(...)`, from which migen's tracer
    cannot derive a unique variable name), so the ports end up called `valid`,
    `first`, `payload_adr` ... . Once several Endpoints collide on a name, migen's
    Namespace appends `_1` to the later one -- producing unreadable and
    unpredictable names like `first` / `first_1` / `dat_1`.

    Here every port is renamed to `<endpoint>_<field>`. Note that this MUST be
    done via `name_override` and not via `sig.name`: port name resolution only
    looks at name_override (see migen/fhdl/namer.py: Namespace.get_name).
    """
    ports = {}
    for ep_name in ENDPOINTS:
        ep = getattr(dut, ep_name, None)
        if ep is None or not hasattr(ep, "layout"):
            continue
        for port_name, sig in flat_fields(ep, ep_name):
            if port_name in ports:
                raise ValueError("duplicate port name: %s" % port_name)
            # Never steal a name somebody already assigned.
            if sig.name_override is None:
                sig.name_override = port_name
            ports[port_name] = sig
    return ports


def build_fragment(dut, ios):
    """Return the DUT fragment plus the ios list that convert() should use.

    Two things have to be handled around clock domains:

    1. **Declare them.** migen's own convert() has
       `create_clock_domains=True` and fills these in automatically, but LiteX's
       convert() has NO such parameter and raises "Unresolved clock domain" as
       soon as it meets an undeclared domain. Going through LiteX therefore means
       declaring them by hand.

    2. **Expose them as ports.** After filling them in, migen's implementation
       also adds `cd.clk` / `cd.rst` to `ios`, which is precisely why
       `<name>_clk` / `<name>_rst` become toplevel ports. LiteX's version does not
       do that, so declaring the ClockDomain alone still leaves clk/rst as
       internal signals and there is no `sys_clk` for cocotb to drive. They are
       added to `ios` explicitly here.

    Note that `Module.get_fragment()` may only be called once (there is a
    `get_fragment_called` assertion inside), so the fragment is fetched once and
    then handed straight to convert() -- never re-fetched from `dut`.
    """
    fragment = dut.get_fragment()
    ios      = set(ios)

    declared = {cd.name for cd in fragment.clock_domains}
    for cd_name in sorted(list_clock_domains(fragment)):
        if cd_name in declared:
            cd = fragment.clock_domains[cd_name]
        else:
            print("[gen_rtl] adding missing ClockDomain(%r)" % cd_name)
            cd = ClockDomain(cd_name)
            fragment.clock_domains.append(cd)
        # ClockDomain already sets name_override to "<name>_clk"/"<name>_rst" on
        # its clk/rst signals, so all that is left is to mark them as IO.
        ios.add(cd.clk)
        if cd.rst is not None:
            ios.add(cd.rst)

    return fragment, ios


def build_dut(data_width, address_width, capabilities, endianness):
    """Instantiate LitePCIe's TLP Packetizer."""
    return LitePCIeTLPPacketizer(
        data_width    = data_width,
        endianness    = endianness,
        address_width = address_width,
        capabilities  = capabilities,
    )


# A port declaration line looks like `input wire [63:0] name` or `output reg name`:
# a direction, an optional wire/reg/logic, an optional bit range, then the name.
PORT_DECL_RE = re.compile(
    r"^\s*(?P<dir>input|output|inout)\s+"
    r"(?:(?:wire|reg|logic)\s+)?"
    r"(?:\[(?P<msb>\d+):(?P<lsb>\d+)\]\s*)?"
    r"(?P<name>\w+)", re.M)


def parse_port_decls(verilog_text):
    """Return [{dir, name, width}] for the toplevel module's port list, in order.

    This walks the module header line by line and stops at the standalone `);`
    that closes it. Do *not* be tempted to do
    `re.search(r"module X\\((.*?)\\);" , text, re.S)`: the closing paren gets
    consumed by the outer match, so the *last* port has no trailing `,` or `)`
    left to anchor on and silently disappears -- which is exactly how `sys_rst`
    went missing from the HTML report's port map.
    """
    lines = verilog_text.splitlines()
    start = next((i for i, ln in enumerate(lines)
                  if re.match(r"\s*module\s+%s\b" % re.escape(TOP), ln)), None)
    if start is None:
        return []

    decls = []
    for ln in lines[start:]:
        if ln.strip() in (");", ")"):
            break
        m = PORT_DECL_RE.match(ln)
        if m:
            msb = m.group("msb")
            decls.append({
                "dir"  : m.group("dir"),
                "name" : m.group("name"),
                "width": (int(msb) + 1) if msb is not None else 1,
            })
    return decls


def main():
    ap = argparse.ArgumentParser(
        description="Export LitePCIe RTL for Verilator + cocotb simulation")
    ap.add_argument("--data-width",    type=int, default=128, choices=[64, 128, 256, 512])
    ap.add_argument("--address-width", type=int, default=64,  choices=[32, 64])
    ap.add_argument("--endianness",    default="big",         choices=["big", "little"])
    ap.add_argument("--capabilities",  default="REQUEST",     choices=["REQUEST", "COMPLETION", "REQUEST,COMPLETION"])
    ap.add_argument("--output",        default=os.path.join(DEMO_ROOT, "rtl", TOP + ".v"))
    ap.add_argument("--print-ports",   action="store_true")
    args = ap.parse_args()

    capabilities = args.capabilities.split(",")
    dut = build_dut(args.data_width, args.address_width, capabilities, args.endianness)
    ports = collect_ports(dut)

    fragment, ios = build_fragment(dut, ports.values())
    text = hdl_convert(fragment, ios=ios, name=TOP)

    header = (
        "// -----------------------------------------------------------------------------\n"
        "// Auto-generated from the LitePCIe (migen/LiteX) sources by rtl/gen_rtl.py.\n"
        "// Do not edit by hand.\n"
        "//   DUT         : litepcie.tlp.packetizer.LitePCIeTLPPacketizer\n"
        "//   data_width  : %d\n"
        "//   addr_width  : %d\n"
        "//   endianness  : %s\n"
        "//   capabilities: %s\n"
        "// -----------------------------------------------------------------------------\n"
    ) % (args.data_width, args.address_width, args.endianness, ",".join(capabilities))

    os.makedirs(os.path.dirname(args.output), exist_ok=True)
    with open(args.output, "w") as f:
        f.write(header + str(text) + "\n")

    # Self-check: make this script guarantee that "the ports that came out == the
    # ports the design asked for". The moment migen appends a `_1` suffix because
    # of an internal name collision, it shows up right here.
    decls   = parse_port_decls(str(text))
    actual  = [d["name"] for d in decls]
    expect  = sorted(ports) + ["sys_clk", "sys_rst"]
    missing = sorted(set(expect) - set(actual))
    extra   = sorted(set(actual) - set(expect))

    print("[gen_rtl] wrote %s" % os.path.relpath(args.output, DEMO_ROOT))
    print("[gen_rtl] toplevel %s: %d ports" % (TOP, len(actual)))
    if args.print_ports:
        for d in decls:
            print("    - %-24s %s[%d]" % (d["name"], d["dir"] + " ", d["width"]))
    if missing or extra:
        print("[gen_rtl] !! port names do not match: missing=%s extra=%s"
              % (missing, extra))
        sys.exit(1)
    print("[gen_rtl] port name self-check passed")

    # Hand the verified port list to whoever needs it downstream (the HTML report
    # draws the port map from this file). Written only after the self-check, so
    # the manifest can never describe a module that failed to build.
    manifest = os.path.splitext(args.output)[0] + ".ports.json"
    with open(manifest, "w") as f:
        json.dump({
            "module"  : TOP,
            "config"  : {
                "data_width"   : args.data_width,
                "address_width": args.address_width,
                "endianness"   : args.endianness,
                "capabilities" : capabilities,
            },
            "ports"   : decls,
        }, f, indent=2)
        f.write("\n")
    print("[gen_rtl] wrote %s" % os.path.relpath(manifest, DEMO_ROOT))


if __name__ == "__main__":
    main()
